"use client";
/* Globe, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Globe(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("globe"); }, []);
  return React.createElement("piix-globe", piixAttrs(props));
}

export default Globe;
